const inp = $input.first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const cand = Number(inp.candidate_id);
const src = Number(inp.source_vacancy_id);
const tgt = Number(inp.target_vacancy_id);
const actionType = String(inp.action_type || '');
if (!cand || !actionType) { throw new Error('propose_action требует candidate_id и action_type'); }
const payload = inp.payload || {};
const sql = "INSERT INTO recruiter_compass.action_proposals (source_review_id, action_type, status, potok_candidate_id, source_vacancy_id, target_vacancy_id, payload, expires_at) SELECT " + (inp.source_review_id ? "'" + esc(String(inp.source_review_id)) + "'" : 'NULL') + ", '" + esc(actionType) + "', 'proposed', " + cand + ", " + src + ", " + tgt + ", '" + esc(JSON.stringify(payload)) + "'::jsonb, now() + interval '7 days' WHERE NOT EXISTS (SELECT 1 FROM recruiter_compass.action_proposals WHERE potok_candidate_id = " + cand + " AND source_vacancy_id = " + src + " AND action_type = '" + esc(actionType) + "' AND status IN ('proposed','consent_required','ready_for_recruiter_confirmation','confirmed')) RETURNING action_id";
return [{ json: { sql: sql } }];

const rows = $input.all();
const created = rows.some(function(r) { return r.json.action_id; });
const actionId = created ? rows.find(function(r) { return r.json.action_id; }).json.action_id : null;
return [{ json: { created: created, action_id: actionId } }];
